let formOpenType=null,formOpenId=null;
function formOgretmenSelect(fieldKey,val,multi){const ogretmenler=arr('ogretmenler').sort((a,b)=>`${a.ad} ${a.soyad}`.localeCompare(`${b.ad} ${b.soyad}`,'tr'));if(multi){const vals=Array.isArray(val)?val:[];return`<select name="${esc(fieldKey)}" multiple size="4">${ogretmenler.map(o=>`<option value="${esc(o.id)}" ${vals.includes(o.id)?'selected':''}>` +`${esc(`${o.ad||''} ${o.soyad||''}`.trim())} (${esc(o.brans||'')})</option>`).join('')}</select><small class="ka-muted">Ctrl/Cmd ile çoklu seçim</small>`}return`<select name="${esc(fieldKey)}"><option value="">— Seçiniz —</option>${ogretmenler.map(o=>`<option value="${esc(o.id)}" ${val===o.id?'selected':''}>${esc(`${o.ad||''} ${o.soyad||''}`.trim())} (${esc(o.brans||'')})</option>`).join('')}</select>`}
function formField(f,item){const v=item?.[f.k]??'';const inp=f.t==='teacher'?formOgretmenSelect(f.k,v,false):f.t==='teachers'?formOgretmenSelect(f.k,v,true):f.t==='textarea'?`<textarea name="${esc(f.k)}">${esc(String(v))}</textarea>`:f.t==='number'?`<input name="${esc(f.k)}" type="number" min="0" value="${esc(String(v))}">`:f.t==='date'?`<input name="${esc(f.k)}" type="date" value="${esc(String(v))}">`:` <input name="${esc(f.k)}" value="${esc(String(v))}" ${f.r?'required':''}>`;return`<label class="ka-field"><span class="ka-field__label">${esc(f.l)}${f.r?' *':''}</span>${inp}</label>`}
