function renderForms(){const types=FORM_TYPES,content=document.getElementById('toolsContent'),count=document.getElementById('toolsCount');const total=types.reduce((n,t)=>n+arr(t).length,0);if(count)count.textContent=`${total} kayıt`;if(!content)return;content.innerHTML=types.map(type=>{const cfg=FORM_COLS[type]||{label:FORM_LABELS[type]||type,title:r=>r.ad||r.baslik||type,fields:[]};const rows=arr(type);return`<section class="ka-stack"><div class="ka-row ka-row--between" style="margin-bottom:4px"><h3 style="font-size:14px">${esc(cfg.label||FORM_LABELS[type]||type)}<span class="ka-badge" style="margin-left:6px">${rows.length}</span></h3><button class="ka-btn ka-btn--sm ka-btn--secondary" type="button" data-form-add="${esc(type)}">+ Ekle</button></div>${rows.length?rows.map(r=>formRecordHtml(type,r,cfg)).join(''):'<div class="ka-empty">Kayıt yok.</div>'}</section>`}).join('');bindForms(content)}
function bindForms(root){if(!root)return;root.querySelectorAll('[data-form-add]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('[data-form-modal]')?.remove();document.body.insertAdjacentHTML('beforeend',formModal(b.dataset.formAdd,{}));_bindFormModal()}));root.querySelectorAll('[data-form-edit]').forEach(b=>b.addEventListener('click',()=>{const t=b.dataset.formType,id=b.dataset.formEdit,item=arr(t).find(x=>x.id===id)||{};document.querySelector('[data-form-modal]')?.remove();document.body.insertAdjacentHTML('beforeend',formModal(t,item));_bindFormModal()}));root.querySelectorAll('[data-form-del]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Bu kayıt silinsin mi?'))return;const t=b.dataset.formType,id=b.dataset.formDel,col=COL?.[t];if(!col||!global.DeviceData)return;try{await global.DeviceData.remove(t,col,id);render()}catch(e){if(typeof toast==='function')toast(e?.message||'Silinemedi')}}));root.querySelectorAll('[data-form-expand]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.formExpand,t=b.dataset.formType;formOpenId=formOpenId===id&&formOpenType===t?null:id;formOpenType=t;renderForms()}))}
function _bindFormModal(){const modal=document.querySelector('[data-form-modal]');if(!modal)return;modal.querySelector('[data-form-modal-kapat]')?.addEventListener('click',()=>modal.remove());modal.addEventListener('click',e=>{if(e.target===modal)modal.remove()});modal.querySelector('#formCizelgeForm')?.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),id=fd.get('id')||'',type=fd.get('formType')||'';const cfg=FORM_COLS[type];if(!cfg){modal.remove();return}const col=COL?.[type];if(!col||!global.DeviceData){if(typeof toast==='function')toast('Koleksiyon bulunamadı');return}const v={};cfg.fields.forEach(f=>{if(f.t==='teachers'){const vals=fd.getAll(f.k);v[f.k]=vals.filter(Boolean)}else if(f.t==='number'){v[f.k]=Number(fd.get(f.k))||0}else{v[f.k]=String(fd.get(f.k)||'').trim()}});try{if(id)await global.DeviceData.update(type,col,id,v);else await global.DeviceData.add(type,col,{...v,olusturmaTarihi:new Date().toISOString()});if(typeof toast==='function')toast('Kaydedildi.');modal.remove();formOpenId=null;render()}catch(err){if(typeof toast==='function')toast(err?.message||'Kaydedilemedi')}})}
function monthDoc(){const y=attendanceDate.getFullYear(),m=attendanceDate.getMonth()+1;return arr('devamsizlikCizelgesi').find(x=>x.id===`${y}-${m}`)||null}
function attCounts(gunler){const vals=Object.values(gunler||{});return {izin:vals.filter(x=>x==='İ').length,rapor:vals.filter(x=>x==='R').length,tatil:vals.filter(x=>x==='T').length,gorev:vals.filter(x=>x==='+').length};}
function attTeacherCard(o,y,m){const gunler=o.gunler||{},c=attCounts(gunler),days=Array.from({length:new Date(y,m,0).getDate()},(_,i)=>i+1);return `<article class="ka-card ka-list-card"><div class="ka-card__body ka-stack"><div class="ka-row ka-row--between"><div><strong>${esc(o.adSoyad||o.ad||o.ogretmenId)}</strong><div class="ka-muted">${esc(o.gorev||'')}</div></div><span class="ka-badge">İ:${c.izin} R:${c.rapor} T:${c.tatil} +:${c.gorev}</span></div><div class="ka-row ka-wrap">${days.map(g=>{const v=gunler[g];return `<button class="ka-btn ka-btn--ghost ka-btn--sm" type="button" data-att-day="${g}" data-att-teacher="${esc(o.ogretmenId||'')}"><span>${g}</span>&nbsp;<strong>${esc(v??'–')}</strong></button>`}).join('')}</div></div></article>`}
function renderAttendance(){const y=attendanceDate.getFullYear(),m=attendanceDate.getMonth()+1,doc=monthDoc(),teachers=Object.values(doc?.ogretmenler||{}),content=document.getElementById('toolsContent'),count=document.getElementById('toolsCount');if(count)count.textContent=`${teachers.length} personel`;if(content)content.innerHTML=`<div class="ka-row ka-row--between"><button class="ka-btn ka-btn--secondary" type="button" data-att-nav="-1">‹ Önceki</button><div><strong>${attendanceDate.toLocaleDateString('tr-TR',{month:'long',year:'numeric'})}</strong><div class="ka-muted">Belge: ${y}-${m}</div></div><button class="ka-btn ka-btn--secondary" type="button" data-att-nav="1">Sonraki ›</button></div>${teachers.length?teachers.map(o=>attTeacherCard(o,y,m)).join(''):'<div class="ka-empty">Bu ay için devamsızlık çizelgesi bulunamadı.</div>'}`;bindAttendance()}
