function bind(){}
function subscribe(){unsubs.forEach(f=>{try{f()}catch(_){}});unsubs=[];const paths=['data.kontrolListeleri','data.kontrolListeTamamlama','data.haritaFavoriler','data.servisler','data.devamsizlikCizelgesi',...(global.ToolsData?.FORM_TYPES||[]).map(t=>'data.'+t)];paths.forEach(p=>{const u=global.AppStore?.subscribe?.(p,()=>requestAnimationFrame(render));if(u)unsubs.push(u)})}
