let currentPage='',currentTitle='',selectedClass='',selectedDate=today(),query='',openBook='',unsubs=[];
function root(){return $('#v2ModuleRoot')}
function setTitle(v){const h=$('#v2ModuleTitle');if(h)h.textContent=v||''}
