function cycleCell(studentId,columnId){if(!draft)return;const key=`${studentId}_${columnId}`,old=draft.hucreler[key]??'';let next='';if(type==='odevTakip')next=old==='✓'?'✗':old==='✗'?'':'✓';else if(draft.hucreModu==='puan'){const v=global.prompt?.('Puan:',String(old));if(v===null)return;next=v.trim();if(next!==''&&(isNaN(Number(next))||Number(next)<0))return global.toast?.('Geçerli bir puan girin.')}else next=old==='+'?'-':old==='-'?'':'+';draft.hucreler[key]=next;markDirty();render()}
